def settings_per_shop(apps, schema_editor):
    """Every shop starts on the card fee set so far; the targets set so far
    were the default shop's (Scentory's are set on Shop settings)."""
    Store = apps.get_model('stock', 'Store')
    BusinessSettings = apps.get_model('stock', 'BusinessSettings')
    SalesTarget = apps.get_model('stock', 'SalesTarget')
    row = BusinessSettings.objects.filter(pk=1).first()
    if row is not None:
        Store.objects.update(card_fee_pct=row.card_fee_pct)
    default = Store.objects.filter(is_default=True).first() or Store.objects.order_by('id').first()
    if default is not None:
        SalesTarget.objects.filter(store__isnull=True).update(store=default)


